92	struct KeysSerializationVersion
93	{
94	    enum Value
95	    {
96	        /// Version is written at the start of <name.dict.bin>.
97	        /// Dictionary is written as number N and N keys after them.
98	        /// Dictionary can be shared for continuous range of granules, so some marks may point to the same position.
99	        /// Shared dictionary is stored in state and is read once.
100	        SharedDictionariesWithAdditionalKeys = 1,
101	    };
102	
103	    Value value;
104	
105	    static void checkVersion(UInt64 version)
106	    {
107	        if (version != SharedDictionariesWithAdditionalKeys)
108	            throw Exception(ErrorCodes::INCORRECT_DATA, "Invalid version for SerializationLowCardinality key column.");
109	    }
110	
111	    explicit KeysSerializationVersion(UInt64 version) : value(static_cast<Value>(version)) { checkVersion(version); }
112	};
