114	/// Version is stored at the start of each granule. It's used to store indexes type and flags.
115	struct IndexesSerializationType
116	{
117	    using SerializationType = UInt64;
118	    /// Need to read dictionary if it wasn't.
119	    static constexpr SerializationType NeedGlobalDictionaryBit = 1u << 8u;
120	    /// Need to read additional keys. Additional keys are stored before indexes as value N and N keys after them.
121	    static constexpr SerializationType HasAdditionalKeysBit = 1u << 9u;
122	    /// Need to update dictionary. It means that previous granule has different dictionary.
123	    static constexpr SerializationType NeedUpdateDictionary = 1u << 10u;
124	
125	    enum Type
126	    {
127	        TUInt8 = 0,
128	        TUInt16,
129	        TUInt32,
130	        TUInt64,
131	    };
132	
133	    Type type;
134	    bool has_additional_keys;
135	    bool need_global_dictionary;
136	    bool need_update_dictionary;
137	
138	    static constexpr SerializationType resetFlags(SerializationType type)
139	    {
140	        return type & (~(HasAdditionalKeysBit | NeedGlobalDictionaryBit | NeedUpdateDictionary));
141	    }
142	
143	    static void checkType(SerializationType type)
144	    {
145	        UInt64 value = resetFlags(type);
146	        if (value <= TUInt64)
147	            return;
148	
149	        throw Exception(ErrorCodes::INCORRECT_DATA, "Invalid type for SerializationLowCardinality index column.");
150	    }
151	
152	    void serialize(WriteBuffer & buffer) const
153	    {
154	        SerializationType val = type;
155	        if (has_additional_keys)
156	            val |= HasAdditionalKeysBit;
157	        if (need_global_dictionary)
158	            val |= NeedGlobalDictionaryBit;
159	        if (need_update_dictionary)
160	            val |= NeedUpdateDictionary;
161	        writeBinaryLittleEndian(val, buffer);
162	    }
163	
164	    void deserialize(ReadBuffer & buffer, const ISerialization::DeserializeBinaryBulkSettings & settings)
165	    {
166	        SerializationType val;
167	        readBinaryLittleEndian(val, buffer);
168	
169	        checkType(val);
170	        has_additional_keys = (val & HasAdditionalKeysBit) != 0;
171	        need_global_dictionary = (val & NeedGlobalDictionaryBit) != 0;
172	        need_update_dictionary = (val & NeedUpdateDictionary) != 0;
173	        type = static_cast<Type>(resetFlags(val));
174	
175	        if (settings.native_format)
176	        {
177	            if (need_global_dictionary)
178	                throw Exception(ErrorCodes::INCORRECT_DATA,
179	                                "LowCardinality indexes serialization type for Native format "
180	                                "cannot use global dictionary");
181	        }
182	    }
