339	    size_t current_task_last_mark,
340	    ISerialization::SubstreamsCache & cache)
341	{
342	    /// If substream have already been read.
343	    if (cache.contains(ISerialization::getSubcolumnNameForStream(substream_path)))
344	        return nullptr;
345	
346	    auto stream_name = IMergeTreeDataPart::getStreamNameForColumn(name_and_type, substream_path, ".bin", checksums, storage_settings);
347	    if (!stream_name)
348	    {
349	        /// We allow missing streams only for columns/subcolumns that are not present in this part.
350	        auto column = data_part_info_for_read->getColumnsDescription().tryGetColumn(GetColumnsOptions::AllPhysical, name_and_type.getNameInStorage());
351	        if (column && (!name_and_type.isSubcolumn() || column->type->hasSubcolumn(name_and_type.getSubcolumnName())))
352	        {
353	            throw Exception(
354	                ErrorCodes::LOGICAL_ERROR,
355	                "Stream {} for column {} with type {} is not found",
356	                ISerialization::getFileNameForStream(
357	                    name_and_type.name, substream_path, ISerialization::StreamFileNameSettings(*storage_settings)),
358	                    name_and_type.name,
359	                    name_and_type.type->getName());
360	        }
361	
362	        return nullptr;
363	    }
364	
365	    auto it = streams.find(*stream_name);
366	    if (it == streams.end())
367	    {
368	        /// If we didn't create requested stream, but file with this path exists, create a stream for it.
369	        /// It may happen during reading of columns with dynamic subcolumns, because all streams are known
370	        /// only after deserializing of binary bulk prefix.
371	
372	        it = addStream(substream_path, *stream_name);
373	    }
374	
375	    MergeTreeReaderStream & stream = *it->second;
376	    stream.adjustRightMark(current_task_last_mark);
377	
378	    if (seek_to_start)
379	        stream.seekToStart();
380	    else if (seek_to_mark)
381	        stream.seekToMark(from_mark);
382	
383	    return stream.getDataBuffer();
384	}
